import json

# Let me try one final approach: what if the interior 3 is NOT preserved but acts as
# part of the pattern itself? Like it has the same properties as border cells locally?

def create_grid():
    n_rows, n_cols = 15, 15
    grid = [[0]*n_cols for _ in range(n_rows)]

    top_row, bottom_row = 2, 10
    left_col, right_col = 3, 11

    for c in range(left_col, right_col + 1):
        grid[top_row][c] = 3
        grid[bottom_row][c] = 3
    for r in range(top_row + 1, bottom_row):
        grid[r][left_col] = 3
        grid[r][right_col] = 3

    grid[5][4] = 3

    return grid

def fill_interior_as_border(grid):
    """Treat interior non-zeros as new borders themselves"""
    output = [row[:] for row in grid]

    # Find all "special" cells (existing non-zeros including interior ones)
    special_cells = []
    top_row, bottom_row = 2, 10
    left_col, right_col = 3, 11

    # Original border frame
    for c in range(left_col, right_col + 1):
        special_cells.append((top_row, c))
        special_cells.append((bottom_row, c))
    for r in range(top_row + 1, bottom_row):
        special_cells.append((r, left_col))
        special_cells.append((r, right_col))

    # Interior non-zeros (the obstacle)
    for r in range(top_row + 1, bottom_row):
        for c in range(left_col + 1, right_col):
            if grid[r][c] != 0:
                special_cells.append((r, c))

    # Compute distance to nearest special cell
    dist_to_special = [[float('inf')] * len(grid[0]) for _ in range(len(grid))]

    for sr, sc in special_cells:
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if (r, c) != (sr, sc):
                    d = min(abs(r - sr), abs(c - sc))
                    dist_to_special[r][c] = min(dist_to_special[r][c], d)

    # Fill empty cells based on distance to nearest special cell
    for r in range(3, 10):
        for c in range(4, 11):
            if grid[r][c] == 0:
                d = dist_to_special[r][c]
                if d != float('inf'):
                    val = 4 if (d % 2 == 1) else 2
                    output[r][c] = val

    return output

grid = create_grid()
output = fill_interior_as_border(grid)

print("Treating interior 3 as special:")
for row in output:
    print(' '.join(map(str, row)))

print(f"\nObstacle at (5,4) preserved: {output[5][4]}")
print(f"Row 5:", ' '.join(map(str, output[5])))

